// Integration tests for Angular with Cerebral state management
import { TestBed } from '@angular/core/testing'
import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
} from '@angular/core'
import { By } from '@angular/platform-browser'
import { CommonModule } from '@angular/common'
import { AppService } from '../src/AppService'
import { CerebralComponent } from '../src/CerebralComponent'
import { connect } from '../src/connect'
import { CerebralTest } from 'cerebral/test'
import { state, sequences } from 'cerebral'

@Component({
  selector: 'test-computed',
  template: '<div data-testid="items">{{filteredItems?.length || 0}}</div>',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
@connect({
  filteredItems: state`filteredItems`,
})
class TestComputedComponent extends CerebralComponent {
  filteredItems!: Array<any>

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) app: AppService
  ) {
    super(cdr, app)
  }
}

@Component({
  selector: 'test-simple',
  template: '<div>{{filteredItems?.length || 0}}</div>',
  standalone: true,
  imports: [CommonModule],
})
class SimpleComponent {
  filteredItems!: any[]

  constructor(private cdr: ChangeDetectorRef) {}

  updateItems(items: any[]) {
    this.filteredItems = items
    this.cdr.detectChanges()
  }
}

@Component({
  selector: 'test-counter',
  template: `
    <div class="count">{{ count }}</div>
    <button class="increment" (click)="increment()">+</button>
    <div class="doubled">{{ doubled }}</div>
  `,
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
@connect({
  count: state`count`,
  doubled: state`doubled`,
  increment: sequences`increment`,
})
class TestCounterComponent extends CerebralComponent {
  count!: number
  doubled!: number
  increment!: () => void

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) app: AppService
  ) {
    super(cdr, app)
  }
}

describe('Angular-Cerebral Integration', () => {
  // Test using a simple component with manual state updates
  it('should integrate computed values with Angular components', async () => {
    const testItems = [
      { id: 1, name: 'Item 1' },
      { id: 2, name: 'Item 2' },
      { id: 3, name: 'Test 3' },
    ]

    const testModule = {
      state: {
        items: testItems,
        filter: '',
        get filteredItems() {
          return this.items.filter((item: any) =>
            this.filter ? item.name.includes(this.filter) : true
          )
        },
      },
      sequences: {
        updateFilter: [
          ({ store, props }: any) => store.set('filter', props.filter),
        ],
      },
    }

    TestBed.configureTestingModule({
      imports: [SimpleComponent],
    })

    const fixture = TestBed.createComponent(SimpleComponent)
    const component = fixture.componentInstance
    const test = CerebralTest(testModule)

    // Initial state - all items
    const items = test.getState('filteredItems')
    component.updateItems(items)
    fixture.detectChanges()

    const displayElement = fixture.nativeElement.querySelector('div')
    expect(displayElement.textContent).toBe('3')

    // Filter to "Item" - 2 items
    test.setState('filter', 'Item')
    component.updateItems(test.getState('filteredItems'))
    fixture.detectChanges()
    expect(displayElement.textContent).toBe('2')

    // Filter to "Test" - 1 item
    test.setState('filter', 'Test')
    component.updateItems(test.getState('filteredItems'))
    fixture.detectChanges()
    expect(displayElement.textContent).toBe('1')
  })

  it('should work with @connect decorator', async () => {
    const testItems = [
      { id: 1, name: 'Item 1' },
      { id: 2, name: 'Item 2' },
      { id: 3, name: 'Test 3' },
    ]

    const testModule = {
      state: {
        items: testItems,
        filter: '',
        filteredItems: testItems,
      },
      sequences: {
        updateFilter: [
          ({ store, props, get }: any) => {
            store.set('filter', props.filter)

            if (props.filter) {
              const items = get(state`items`)
              store.set(
                'filteredItems',
                items.filter((item: any) => item.name.includes(props.filter))
              )
            } else {
              store.set('filteredItems', get(state`items`))
            }
          },
        ],
      },
    }

    const appService = new AppService(testModule)

    await TestBed.configureTestingModule({
      imports: [TestComputedComponent],
      providers: [{ provide: AppService, useValue: appService }],
    }).compileComponents()

    const fixture = TestBed.createComponent(TestComputedComponent)
    const component = fixture.componentInstance
    fixture.detectChanges()

    const countElement = fixture.debugElement.query(
      By.css('[data-testid="items"]')
    ).nativeElement

    // Initial state - 3 items
    expect(countElement.textContent).toBe('3')
    expect(component.filteredItems.length).toBe(3)

    // Filter to "Item" - 2 items
    appService.getSequence('updateFilter')({ filter: 'Item' })
    appService.flush()
    fixture.detectChanges()

    expect(countElement.textContent).toBe('2')
    expect(component.filteredItems.length).toBe(2)

    // Filter to "Test" - 1 item
    appService.getSequence('updateFilter')({ filter: 'Test' })
    appService.flush()
    fixture.detectChanges()

    expect(countElement.textContent).toBe('1')
    expect(component.filteredItems.length).toBe(1)
  })

  it('should integrate with Cerebral using counter example', async () => {
    const testModule = {
      state: {
        count: 1,
        get doubled() {
          return this.count * 2
        },
      },
      sequences: {
        increment: [
          ({ store, get }: any) => store.set('count', get(state`count`) + 1),
        ],
      },
    }

    const appService = new AppService(testModule)

    await TestBed.configureTestingModule({
      imports: [TestCounterComponent],
      providers: [{ provide: AppService, useValue: appService }],
    }).compileComponents()

    const fixture = TestBed.createComponent(TestCounterComponent)
    fixture.detectChanges()

    const countElement = fixture.debugElement.query(By.css('.count'))
    const doubledElement = fixture.debugElement.query(By.css('.doubled'))
    const incrementButton = fixture.debugElement.query(By.css('.increment'))

    // Initial state
    expect(countElement.nativeElement.textContent.trim()).toBe('1')
    expect(doubledElement.nativeElement.textContent.trim()).toBe('2')

    // Increment count
    incrementButton.triggerEventHandler('click', null)
    appService.flush()
    fixture.detectChanges()

    // Updated state
    expect(countElement.nativeElement.textContent.trim()).toBe('2')
    expect(doubledElement.nativeElement.textContent.trim()).toBe('4')
  })
})
